const shadowProfitByAccountDay = `-- name: ShadowProfitByAccountDay :many
SELECT
    pd.account_id::text                  AS account_id,
    pd.business_day                      AS business_day,
    COUNT(*)::bigint                     AS row_count,
    COUNT(pd.revenue_minor)::bigint      AS revenue_known_rows,
    COUNT(pd.cost_minor)::bigint         AS cost_known_rows,
    COALESCE(SUM(pd.revenue_minor), 0)::bigint AS revenue_minor_sum,
    COALESCE(SUM(pd.cost_minor), 0)::bigint    AS cost_minor_sum,
    COUNT(DISTINCT pd.currency)::bigint  AS currency_count,
    MIN(pd.currency)::text               AS currency,
    COUNT(DISTINCT pd.business_day_tz)::bigint AS business_day_tz_count,
    MIN(pd.business_day_tz)::text        AS business_day_tz
FROM finance.profit_daily pd
JOIN finance.upstream_account ua ON ua.id = pd.upstream_account_id
WHERE ua.environment   = $1
  AND ua.access_method = 'upstream_key'
  AND pd.business_day >= $2
  AND pd.business_day <= $3
GROUP BY pd.account_id, pd.business_day
ORDER BY pd.business_day, pd.account_id
`

type ShadowProfitByAccountDayParams struct {
	Environment string
	FromDay     pgtype.Date
	ToDay       pgtype.Date
}

type ShadowProfitByAccountDayRow struct {
	AccountID          string
	BusinessDay        pgtype.Date
	RowCount           int64
	RevenueKnownRows   int64
	CostKnownRows      int64
	RevenueMinorSum    int64
	CostMinorSum       int64
	CurrencyCount      int64
	Currency           string
	BusinessDayTzCount int64
	BusinessDayTz      string
}

// 影子对比的平台侧取数（XM-0037e，设计稿 §9）。
//
// 粒度是 **(account_id, business_day)**：SoloAI 的 relay_profit_daily 主键是
// (station_id, day, token_id)，两侧都按 account_id 聚合掉令牌维度才配得上对
// （§9 的对比 SQL 就是这么写的）。account_id 在两边是同一个东西——都是令牌
// 映射表的**值**（sub2api 为自营账号 id，newapi 为 channel_id）。
//
// **只取 access_method='upstream_key'**：影子对比的范围就是计量型渠道（§9）。
// 订阅型与 official_api 在 SoloAI 侧没有对象，混进来会全部变成「平台有、
// SoloAI 无」的假差异，把真差异淹掉。
//
// 金额留在 scale-6 微单位**不在 SQL 里折分**：折算规则（半进）要与 SoloAI 侧
// 用同一份代码，写进 SQL 就变成两份实现了。SUM 用 bigint 保持整数（宪法 13 条）。
//
// 未知（NULL）与已知 0 必须分得开（§5.1）。这里靠**两个**字段表达，
// 而不是靠一个可空的 SUM：
//
//	known_rows = 0        → 这个账号这天该侧**整天未知**（SUM 无意义）
//	0 < known_rows < rows → 部分未知（SUM 只含已知行，报告里要标出来）
//	known_rows = rows     → 全部已知
//
// SUM 本身 COALESCE 到 0：SUM 会跳过 NULL，所以它在 known_rows>0 时就是
// 「已知行之和」；用 known_rows 判未知比让 sqlc 生成一个可空整数更直白，
// 也与 SumProfitDailyByPlatform 的写法一致。
func (q *Queries) ShadowProfitByAccountDay(ctx context.Context, arg ShadowProfitByAccountDayParams) ([]ShadowProfitByAccountDayRow, error) {
	rows, err := q.db.Query(ctx, shadowProfitByAccountDay, arg.Environment, arg.FromDay, arg.ToDay)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ShadowProfitByAccountDayRow{}
	for rows.Next() {
		var i ShadowProfitByAccountDayRow
		if err := rows.Scan(
			&i.AccountID,
			&i.BusinessDay,
			&i.RowCount,
			&i.RevenueKnownRows,
			&i.CostKnownRows,
			&i.RevenueMinorSum,
			&i.CostMinorSum,
			&i.CurrencyCount,
			&i.Currency,
			&i.BusinessDayTzCount,
			&i.BusinessDayTz,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const sumProfitDailyByPlatform = `-- name: SumProfitDailyByPlatform :many
SELECT
    CASE
        WHEN pd.platform_id IS NULL THEN 'unattributed'
        WHEN EXISTS (
            SELECT 1 FROM core.service s
            WHERE s.instance_id = pd.platform_id
              AND s.environment = ua.environment
              AND s.status <> 'retired'
        ) THEN 'platform'
        ELSE 'removed_platform'
    END::text AS bucket,
    pd.platform_id                             AS platform_id,
    COUNT(*)::bigint                           AS row_count,
    COUNT(pd.revenue_minor)::bigint            AS revenue_known_rows,
    COUNT(pd.cost_minor)::bigint               AS cost_known_rows,
    COALESCE(SUM(pd.revenue_minor), 0)::bigint AS revenue_minor_sum,
    COALESCE(SUM(pd.cost_minor), 0)::bigint    AS cost_minor_sum,
    COUNT(DISTINCT pd.currency)::bigint        AS currency_count,
    MIN(pd.currency)::text                     AS currency
FROM finance.profit_daily pd
JOIN finance.upstream_account ua ON ua.id = pd.upstream_account_id
WHERE ua.environment  = $1
  AND pd.business_day >= $2
  AND pd.business_day <= $3
GROUP BY 1, pd.platform_id
ORDER BY 1, pd.platform_id NULLS LAST
`

type SumProfitDailyByPlatformParams struct {
	Environment string
	FromDay     pgtype.Date
	ToDay       pgtype.Date
}

type SumProfitDailyByPlatformRow struct {
	Bucket           string
	PlatformID       *string
	RowCount         int64
	RevenueKnownRows int64
	CostKnownRows    int64
	RevenueMinorSum  int64
	CostMinorSum     int64
	CurrencyCount    int64
	Currency         string
}

// 平台归属四桶（§5.2）：有效平台 / 指向已移除平台 / 未归属，各自成桶。
//
// **不 COALESCE platform_id**：把 NULL 折成 'unknown' 之类的字符串会让
// 「未归属」与「有一个叫 unknown 的平台」再也分不开。
// **不 INNER JOIN core.service**：那会把「指向已移除平台」的行整批静默丢掉，
// 金额凭空少一块而总数看起来毫无异常——这正是本纪律要挡的事。
//
// 用 EXISTS 而不是设计稿 §5.2 字面写的 LEFT JOIN：core.service 的唯一键是
// (service_type, instance_id)，只按 instance_id 左连会在同名不同类型时**放大行数**，
// 而放大之后恒等式（四桶行数之和 == 独立窗口计数）会以一种非常难查的方式失败。
// EXISTS 保留了 LEFT JOIN 的意图（不丢行），且结构上不可能改变行数。
//
// 金额列可空（§5.1 的 NULL=未知），所以除了 SUM 还回 `*_known_rows`：
// SUM 会跳过 NULL，只给和不给覆盖行数，调用方无从判断这个和代表了几行。
// 币种不同的最小单位不能相加，故一并回 currency_count 让调用方自己分桶。
func (q *Queries) SumProfitDailyByPlatform(ctx context.Context, arg SumProfitDailyByPlatformParams) ([]SumProfitDailyByPlatformRow, error) {
	rows, err := q.db.Query(ctx, sumProfitDailyByPlatform, arg.Environment, arg.FromDay, arg.ToDay)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SumProfitDailyByPlatformRow{}
	for rows.Next() {
		var i SumProfitDailyByPlatformRow
		if err := rows.Scan(
			&i.Bucket,
			&i.PlatformID,
			&i.RowCount,
			&i.RevenueKnownRows,
			&i.CostKnownRows,
			&i.RevenueMinorSum,
			&i.CostMinorSum,
			&i.CurrencyCount,
			&i.Currency,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const sumRecentCostByAccount = `-- name: SumRecentCostByAccount :many
SELECT
    pd.upstream_account_id                  AS upstream_account_id,
    COALESCE(SUM(pd.cost_minor), 0)::bigint AS cost_minor_sum,
    COUNT(DISTINCT pd.business_day) FILTER (WHERE pd.cost_minor IS NOT NULL)::bigint
                                            AS covered_days,
    COUNT(DISTINCT pd.currency)::bigint     AS currency_count,
    MIN(pd.currency)::text                  AS currency
FROM finance.profit_daily pd
JOIN finance.upstream_account ua ON ua.id = pd.upstream_account_id
WHERE ua.environment  = $1
  AND pd.business_day >= $2
  AND pd.business_day <= $3
  AND pd.cost_minor IS NOT NULL
GROUP BY pd.upstream_account_id
`

type SumRecentCostByAccountParams struct {
	Environment string
	FromDay     pgtype.Date
	ToDay       pgtype.Date
}

type SumRecentCostByAccountRow struct {
	UpstreamAccountID uuid.UUID
	CostMinorSum      int64
	CoveredDays       int64
	CurrencyCount     int64
	Currency          string
}

// 可用天数的**分母**：某环境下每个账号在窗口内的已知成本之和与覆盖天数（§10.4）。
//
// 与上面那条分开而不是复用：两者的窗口不同，且**必须不同**——
// 看板的窗口由调用方给（默认今天），而日均消耗固定取近 7 个**完整**业务日
// （不含今天：今天还在累积，算进去会让日均偏低、可用天数虚高）。
//
// covered_days 数的是**有已知成本的业务日**，不是窗口天数：只采到 3 天数据时
// 除以 7 会把日均压低到实际的四成，可用天数因而虚高一倍多——
// 一个偏乐观的预警值，正好是最危险的方向。日均由调用方用这两个数去除。
//
// 「该上游全部映射渠道」（§10.4）在这里就是按 upstream_account_id 分组：
// 一个上游账号名下的全部令牌都写进同一个 upstream_account_id 的行
// （令牌级行 + 账号级聚合行都算），SUM 天然覆盖到它们。
func (q *Queries) SumRecentCostByAccount(ctx context.Context, arg SumRecentCostByAccountParams) ([]SumRecentCostByAccountRow, error) {
	rows, err := q.db.Query(ctx, sumRecentCostByAccount, arg.Environment, arg.FromDay, arg.ToDay)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SumRecentCostByAccountRow{}
	for rows.Next() {
		var i SumRecentCostByAccountRow
		if err := rows.Scan(
			&i.UpstreamAccountID,
			&i.CostMinorSum,
			&i.CoveredDays,
			&i.CurrencyCount,
			&i.Currency,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const summarizeProfitDailyByAccount = `-- name: SummarizeProfitDailyByAccount :many
SELECT
    pd.upstream_account_id                     AS upstream_account_id,
    COUNT(*)::bigint                           AS row_count,
    COUNT(pd.revenue_minor)::bigint            AS revenue_known_rows,
    COUNT(pd.cost_minor)::bigint               AS cost_known_rows,
    COALESCE(SUM(pd.revenue_minor), 0)::bigint AS revenue_minor_sum,
    COALESCE(SUM(pd.cost_minor), 0)::bigint    AS cost_minor_sum,
    COUNT(DISTINCT pd.currency)::bigint        AS currency_count,
    MIN(pd.currency)::text                     AS currency,
    COUNT(*) FILTER (WHERE pd.token_id LIKE 'account:%')::bigint AS account_grain_rows,
    -- 显式 ::timestamptz：不加的话 sqlc 推不出 MIN/MAX 的类型，
    -- 生成的字段会是 interface{}，于是「观测时刻」在 Go 侧变成一个
    -- 要靠类型断言才能用的东西——那正是最容易漏判 NULL 的形状。
    MIN(pd.cost_observed_at)::timestamptz       AS oldest_cost_observed_at,
    MIN(pd.revenue_observed_at)::timestamptz    AS oldest_revenue_observed_at,
    MAX(pd.updated_at)::timestamptz             AS latest_updated_at,
    MIN(pd.source)::text                       AS source
FROM finance.profit_daily pd
JOIN finance.upstream_account ua ON ua.id = pd.upstream_account_id
WHERE ua.environment  = $1
  AND pd.business_day >= $2
  AND pd.business_day <= $3
GROUP BY pd.upstream_account_id
`

type SummarizeProfitDailyByAccountParams struct {
	Environment string
	FromDay     pgtype.Date
	ToDay       pgtype.Date
}

type SummarizeProfitDailyByAccountRow struct {
	UpstreamAccountID       uuid.UUID
	RowCount                int64
	RevenueKnownRows        int64
	CostKnownRows           int64
	RevenueMinorSum         int64
	CostMinorSum            int64
	CurrencyCount           int64
	Currency                string
	AccountGrainRows        int64
	OldestCostObservedAt    pgtype.Timestamptz
	OldestRevenueObservedAt pgtype.Timestamptz
	LatestUpdatedAt         pgtype.Timestamptz
	Source                  string
}

// 看板供数的主查询：某环境、某业务日区间，**按上游账号上卷**的收入/成本/毛利。
//
// 渠道键 = `upstream_account`（§12.2 的默认裁定，037d 沿用）：令牌是它的下钻，
// 下钻行走 GET /api/v1/finance/profit-daily。
//
// 三组「覆盖率」列与金额一起回，缺一不可（宪法 12 条）：
//
//	row_count                总行数；
//	revenue_known_rows/cost_known_rows  该侧非 NULL 的行数——SUM 会跳过 NULL，
//	                         只给和不给覆盖行数，调用方无从判断这个和代表了几行；
//	currency_count           不同币种的最小单位不能相加，>1 时那个和是错数。
//
// 观测时刻取**最旧**的那个（MIN）：聚合值的新鲜度由最不新鲜的成员决定，
// 取最新会让一条刚刷新的行替其余几十条陈旧的读数背书。
//
// account_grain_rows 数的是账号级聚合行（token_id 以 'account:' 开头，
// XM-0037c）。它单独回报是因为那些行**没有独立的令牌下钻**——
// 前端要能说出「这个渠道的 3 行里有 1 行是账号级聚合」，而不是让人点开一个空表。
func (q *Queries) SummarizeProfitDailyByAccount(ctx context.Context, arg SummarizeProfitDailyByAccountParams) ([]SummarizeProfitDailyByAccountRow, error) {
	rows, err := q.db.Query(ctx, summarizeProfitDailyByAccount, arg.Environment, arg.FromDay, arg.ToDay)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SummarizeProfitDailyByAccountRow{}
	for rows.Next() {
		var i SummarizeProfitDailyByAccountRow
		if err := rows.Scan(
			&i.UpstreamAccountID,
			&i.RowCount,
			&i.RevenueKnownRows,
			&i.CostKnownRows,
			&i.RevenueMinorSum,
			&i.CostMinorSum,
			&i.CurrencyCount,
			&i.Currency,
			&i.AccountGrainRows,
			&i.OldestCostObservedAt,
			&i.OldestRevenueObservedAt,
			&i.LatestUpdatedAt,
			&i.Source,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

