// 登记或改写一条令牌映射。
//
// ON CONFLICT DO UPDATE 而不是先查后写：映射是「这个上游令牌对应哪个自营
// 账号」的**当前事实**，重复登记同一个令牌就是在纠正它，不该报唯一冲突
// 让运营去猜要先删再加。
func (q *Queries) UpsertTokenMapping(ctx context.Context, arg UpsertTokenMappingParams) (FinanceTokenMap, error) {
	row := q.db.QueryRow(ctx, upsertTokenMapping,
		arg.UpstreamAccountID,
		arg.UpstreamTokenID,
		arg.OwnAccountID,
		arg.CredentialRef,
	)
	var i FinanceTokenMap
	err := row.Scan(
		&i.UpstreamAccountID,
		&i.UpstreamTokenID,
		&i.OwnAccountID,
		&i.CredentialRef,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
